/* Hotelska oprema partner portal — self-contained, browser-local demonstration. */
(() => {
 'use strict';
 const D=window.DEMO_DATA, KEY='hotelska-oprema-partner-v3';
 const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',bag:'<path d="M5 7h14l2 14H3L5 7Z"/><path d="M8 7V5a4 4 0 0 1 8 0v2"/>',shirt:'<path d="m8 3-6 4 3 5 3-2v11h8V10l3 2 3-5-6-4a4 4 0 0 1-8 0Z"/>',repeat:'<path d="m17 2 4 4-4 4M3 10V8a2 2 0 0 1 2-2h16M7 22l-4-4 4-4m14 0v2a2 2 0 0 1-2 2H3"/>',orders:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 4V2h6v2M9 9h6M9 13h6M9 17h4"/>',quote:'<path d="M20 11v8a2 2 0 0 1-2 2H4V4a2 2 0 0 1 2-2h8l6 6v3Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',docs:'<path d="M8 3h9l4 4v14H8Z"/><path d="M8 7H3v14M17 3v5h4M12 12h5M12 16h5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M2 21v-3a5 5 0 0 1 5-5h4a5 5 0 0 1 5 5v3M17 5a3 3 0 0 1 0 6m2 3a4 4 0 0 1 3 4v3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 .5c0 2-2.5 2-2.5 4M12 17h.01"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',switch:'<path d="M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M3 16v5h18v-5"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 6 10 7L22 6"/>',phone:'<path d="m4 3 4-1 3 6-3 2a16 16 0 0 0 6 6l2-3 6 3-1 4c-1 4-9 0-13-4S0 4 4 3Z"/>',box:'<path d="m12 2 10 5v10l-10 5L2 17V7l10-5Zm0 10v10M2 7l10 5 10-5M7 4.5l10 5V14"/>',truck:'<path d="M1 4h14v13H1Zm14 5h4l4 5v3h-8"/><circle cx="5" cy="19" r="2"/><circle cx="19" cy="19" r="2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',chart:'<path d="M3 3v18h18M7 16v-5m5 5V7m5 9v-8"/>',tag:'<path d="m3 3 9 0 10 10-9 9L3 12V3Z"/><circle cx="7.5" cy="7.5" r="1"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',logout:'<path d="M10 3H3v18h7m4-15 6 6-6 6M7 12h13"/>'};
 const ic=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.box}</svg>`;
 const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>new Intl.NumberFormat('sr-Latn-RS',{maximumFractionDigits:0}).format(Number(n)||0)+' RSD';
 const date=s=>new Date(s+'T12:00:00').toLocaleDateString('sr-Latn-RS',{day:'numeric',month:'short',year:'numeric'});
 const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Belgrade'});
 const clone=x=>JSON.parse(JSON.stringify(x));
 let storageOK=true, state;
 const fresh=()=>({version:3,mode:'buyer',profileId:'aurora',cart:[],orders:clone(D.orders),quotes:clone(D.quotes),customers:clone(D.customers),inventory:clone(D.inventory),favorites:[],visits:0});
 try{const s=JSON.parse(localStorage.getItem(KEY)||'null');state=s?.version===3?s:fresh();}catch{state=fresh();storageOK=false;}
 function wireLabels(root){root.querySelectorAll('.form-group').forEach((g,i)=>{const label=g.querySelector('label'),input=g.querySelector('input,select,textarea');if(label&&input&&!label.htmlFor){if(!input.id)input.id='field-'+(root.id||'modal')+'-'+i;label.htmlFor=input.id;}});}
 let view='dashboard',filters={q:'',category:'all',role:'all',available:false,favorites:false,sort:'recommended'},orderFilter='all',adminSearch='',importRows=[],modalReturn=null;
 const products=D.products, product=id=>products.find(p=>p.id===id), customer=()=>state.customers.find(c=>c.id===state.profileId)||state.customers[0], isAdmin=()=>state.mode==='admin';
 const price=(p,c=customer())=>Math.round(p.demoPrice*(1-c.discount/100));
 const linePrice=l=>l.unitPrice??price(product(l.productId));
 const total=items=>items.reduce((s,l)=>s+linePrice(l)*l.qty,0);
 const cartCount=()=>state.cart.reduce((s,l)=>s+l.qty,0);
 const mineOrders=()=>state.orders.filter(o=>o.customerId===state.profileId);
 const myQuotes=()=>state.quotes.filter(q=>q.customerId===state.profileId);
 const stock=p=>state.inventory[p.id]??0;
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}};
 function toast(msg){const e=document.getElementById('toast');e.textContent=msg;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),3500);}
 const statuses={received:['Primljena','blue'],confirmed:['Potvrđena','green'],production:['U pripremi','orange'],shipped:['Poslata','blue'],delivered:['Isporučena','green'],cancelled:['Otkazana','red']};
 const quoteStatuses={requested:['Zahtev primljen','orange'],offered:['Ponuda spremna','blue'],accepted:['Prihvaćena','green']};
 const badge=(s,quote=false)=>{const a=(quote?quoteStatuses:statuses)[s]||[s,''];return `<span class="badge ${a[1]}"><span class="pill-dot"></span>${a[0]}</span>`;};
 function title(){const t={dashboard:isAdmin()?'Pregled poslovanja':'Vaš poslovni nalog',catalog:'Katalog proizvoda',programs:'Naše uniforme',quick:'Brza porudžbina',orders:'Porudžbine',quotes:'Ponude i zahtevi',documents:'Dokumenti',account:'Podaci o nalogu',help:'Pomoć i podrška',cart:'Vaša korpa',customers:'Poslovni kupci',inventory:'Artikli i zalihe',pricing:'Cene i uslovi',pilot:'Usvajanje portala'};return t[view]||t.dashboard;}
 function navigation(){return isAdmin()?[['dashboard','home','Pregled'],['orders','orders','Porudžbine'],['quotes','quote','Ponude i zahtevi'],['customers','users','Kupci'],['inventory','box','Artikli i zalihe'],['pricing','tag','Cene i uslovi'],['pilot','chart','Pilot i aktivacija']]:[['dashboard','home','Početna'],['catalog','bag','Katalog proizvoda'],['programs','shirt','Naše uniforme'],['quick','upload','Brza porudžbina'],['orders','orders','Moje porudžbine'],['quotes','quote','Ponude i zahtevi'],['documents','docs','Dokumenti']];}
 function render(){
  const c=customer(),a=isAdmin();
  document.getElementById('app').innerHTML=`<aside class="sidebar" id="sidebar"><button class="mobile-close" data-action="menu-close" aria-label="Zatvori meni">×</button><a class="brandmark" href="#dashboard"><img class="brand-logo" src="./assets/logo.png" alt="Hotelska oprema by Fashion story"></a><div class="nav-label">${a?'ADMINISTRACIJA':'PARTNER PORTAL'}</div><nav class="nav-list">${navigation().map(([v,i,t])=>`<a href="#${v}" class="nav-item ${view===v?'active':''}">${ic(i)}<span>${t}</span>${v==='orders'?`<span class="nav-count">${(a?state.orders:mineOrders()).filter(o=>!['delivered','cancelled'].includes(o.status)).length}</span>`:''}</a>`).join('')}</nav><div class="nav-label">${a?'DEMONSTRACIJA':'VAŠ NALOG'}</div><nav class="nav-list">${!a?`<a href="#account" class="nav-item ${view==='account'?'active':''}">${ic('user')}Moj nalog</a>`:''}<a href="#help" class="nav-item ${view==='help'?'active':''}">${ic('help')}Pomoć i podrška</a><button data-action="profiles" class="nav-item">${ic('switch')}Promeni nalog</button></nav><div class="sidebar-bottom"><div class="sidebar-note"><span class="eyebrow">${a?'MALI KORACI. JASNI REZULTATI.':'VAŠ TIM, VAŠ IZBOR.'}</span><strong>${a?'Počnite sa pilot grupom.':'Uniforme bez ponovnog dogovaranja.'}</strong><p>${a?'Pogledajte ko je aktivirao nalog i napravio prvu porudžbinu.':'Sačuvani modeli, veličine i personalizacija za vaš objekat.'}</p><button class="text-btn" data-action="${a?'go-pilot':'go-programs'}">${a?'Otvori pilot':'Naše uniforme'} ${ic('arrow')}</button></div><div class="account-card"><span class="avatar">${a?'DS':esc(c.initials)}</span><span><strong>${a?'Dejan Savić':esc(c.contact)}</strong><small>${a?'Administracija · Demo':esc(c.name)}</small></span></div></div></aside><div class="mobile-shade" data-action="menu-close"></div><div class="workspace"><header class="topbar"><div class="flex"><button class="icon-btn mobile-nav-btn" data-action="menu" aria-label="Otvori meni">${ic('menu')}</button><div class="breadcrumb"><span class="desktop-only">${a?'Administracija':esc(c.name)}</span><span class="desktop-only">/</span><strong>${title()}</strong></div></div><div class="top-actions">${!a?`<form class="top-search" id="top-search">${ic('search')}<input aria-label="Pretraži katalog" name="q" placeholder="Pronađite proizvod ili šifru…"></form>`:''}<button class="mode-btn" data-action="toggle-mode">${ic(a?'user':'shield')}${a?'Prikaz kupca':'Administracija'} ${ic('arrow')}</button>${!a?`<a href="#cart" class="cart-top" aria-label="Korpa, ${cartCount()} komada">${ic('bag')}<span>${cartCount()}</span></a>`:`<button class="avatar" data-action="profiles" aria-label="Promeni profil">DS</button>`}</div></header><div class="demo-strip">${ic('info')}<span>DEMO PORTAL <span class="optional">· Izgled i tok rada za razgovor sa Dejanom.</span> Cene, zalihe i nalozi su ilustrativni.</span><button data-action="demo-info">O demou</button></div>${!storageOK?'<div class="storage-note">Pregledač ne dozvoljava čuvanje podataka. Promene važe dok je ova stranica otvorena.</div>':''}<main class="content" id="main">${page()}<footer class="footer"><span>© 2026 Hotelska oprema · Prototip za poslovne kupce</span><span>Pokreće <strong>B2Bware</strong> <span> / </span> Integracije <strong>SyncSpider</strong></span></footer></main></div>`;
  wireLabels(document.getElementById('app'));
 }
 const heading=(h,p,action='')=>`<div class="page-heading"><div><h1>${h}</h1><p>${p}</p></div>${action}</div>`;
 function kpi(label,value,sub,icon='chart',positive=false){return `<div class="kpi"><span class="kpi-icon">${ic(icon)}</span><div class="kpi-label">${label}</div><div class="kpi-number">${value}</div><div class="kpi-sub ${positive?'positive':''}">${sub}</div></div>`;}
 function card(p){return `<article class="product-card"><div class="product-image" data-action="product" data-id="${p.id}" tabindex="0" role="button" aria-label="Detalji: ${esc(p.name)}"><span class="badge ${p.category==='uniforme'?'':'green'}">${p.category==='uniforme'?'Personalizacija':stock(p)>0?'Dostupno':'Po porudžbini'}</span><button class="favorite ${state.favorites.includes(p.id)?'on':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.favorites.includes(p.id)?'Ukloni iz':'Dodaj u'} omiljene">${ic('heart')}</button><img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy"></div><div class="product-body"><div class="product-role">${esc(p.role)}</div><button class="product-title" data-action="product" data-id="${p.id}">${esc(p.name)}</button><div class="product-meta">${esc(p.sku)} · ${p.sizes.length>1?esc(p.sizes[0]+'–'+p.sizes[p.sizes.length-1]):esc(p.sizes[0])}</div><div class="product-bottom"><div class="product-price">${money(price(p))}<small>vaša demo cena / kom</small></div><button class="add-btn" data-action="product" data-id="${p.id}" aria-label="Izaberi veličine za ${esc(p.name)}">${ic('plus')}</button></div></div></article>`;}
 function page(){switch(view){case'dashboard':return isAdmin()?adminDashboard():dashboard();case'catalog':return catalog();case'programs':return programs();case'quick':return quick();case'orders':return ordersPage();case'quotes':return quotesPage();case'documents':return documentsPage();case'account':return accountPage();case'help':return helpPage();case'cart':return cartPage();case'customers':return customersPage();case'inventory':return inventoryPage();case'pricing':return pricingPage();case'pilot':return pilotPage();default:return dashboard();}}
 function dashboard(){const c=customer(),oo=mineOrders(),active=oo.filter(o=>!['delivered','cancelled'].includes(o.status)),featured=products.filter(p=>c.approved.includes(p.id)).slice(0,4);return `${heading('Dobro došli, '+esc(c.firstName)+'.','Sve za vaš tim. Jednostavnije, na jednom mestu.',`<span class="date-label">Partner nalog · ${esc(c.name)}</span>`)}<section class="hero"><div class="hero-copy"><div class="eyebrow">KOLEKCIJA ZA VAŠ TIM · 2026</div><h2>Vaš tim.<br>Prepoznatljiv u<br>svakom detalju.</h2><p>Odobreni modeli, vaše veličine i vaš logo.<br>Sledeća nabavka počinje tamo gde je prethodna stala.</p><a class="btn" href="#programs">Pogledajte naše uniforme ${ic('arrow')}</a></div><div class="hero-visual"><span class="hero-toplabel">${ic('check').replace('class="icon"','style="width:10px;height:10px;vertical-align:middle" class="icon"')} Personalizovano za ${esc(c.shortName)}</span><img src="${D.hero}" alt="Profesionalna uniforma iz asortimana Hotelske opreme"><span class="hero-caption">DOBAR UTISAK POČINJE DETALJIMA</span></div></section><div class="kpi-grid">${kpi('Aktivne porudžbine',active.length,'Pratite svaki korak isporuke','orders')}${kpi('Odobreni modeli',c.approved.length,'Spremni za ponovnu nabavku','shirt')}${kpi('Vaši ugovoreni uslovi',c.discount+'%','Ilustrativan rabat na demo cene','tag')}${kpi('Rok plaćanja',c.paymentDays+' dana','Demo uslovi za vaš objekat','clock')}</div><section><div class="section-head"><div><h2>Izabrano za vaš objekat</h2><p>Modeli koje vaš tim već poznaje.</p></div><a href="#catalog" class="text-btn">Ceo katalog ${ic('arrow')}</a></div><div class="product-grid featured">${featured.map(card).join('')}</div></section><div class="dashboard-lower"><section class="panel"><div class="section-head"><h2>Poslednje porudžbine</h2><a href="#orders" class="text-btn">Sve porudžbine ${ic('arrow')}</a></div>${oo.slice(0,3).map(o=>`<div class="order-mini"><span class="square-icon">${ic('orders')}</span><div><button class="text-btn" data-action="order" data-id="${o.id}">${o.id}</button><p>${date(o.date)} · ${o.items.reduce((s,l)=>s+l.qty,0)} komada · ${money(total(o.items))}</p></div>${badge(o.status)}</div>`).join('')||'<p class="muted">Još nema porudžbina.</p>'}</section><section class="panel help-panel"><div class="eyebrow">PODRŠKA PRI IZBORU</div><h2>Novi tim?<br>Novi izgled?</h2><p>Za poseban model, drugačiju specifikaciju ili veće količine, pošaljite nam zahtev. Zajedno biramo detalje.</p><button class="text-btn" data-action="quote-new">Zatražite ponudu ${ic('arrow')}</button></section></div>`;}
 function catalog(){let pp=products.filter(p=>(filters.category==='all'||p.category===filters.category)&&(filters.role==='all'||p.role===filters.role)&&(!filters.available||stock(p)>0)&&(!filters.favorites||state.favorites.includes(p.id))&&(!filters.q||(p.name+' '+p.sku+' '+p.role).toLocaleLowerCase('sr').includes(filters.q.toLocaleLowerCase('sr'))));if(filters.sort==='price-up')pp.sort((a,b)=>price(a)-price(b));if(filters.sort==='price-down')pp.sort((a,b)=>price(b)-price(a));if(filters.sort==='name')pp.sort((a,b)=>a.name.localeCompare(b.name,'sr'));const roles=[...new Set(products.filter(p=>filters.category==='all'||p.category===filters.category).map(p=>p.role))];return `${heading('Katalog proizvoda','Pronađite pravi izbor za ljude koji predstavljaju vaš objekat.',`<a href="#quick" class="btn light small">${ic('upload')}Uvoz porudžbine</a>`)}<div class="catalog-layout"><aside class="filters"><div class="filter-block"><h3>Asortiman</h3>${[['all','Svi proizvodi'],['uniforme','Uniforme'],['tekstil','Hotelski tekstil']].map(([v,t])=>`<label class="filter-option"><input type="radio" name="category" data-filter="category" value="${v}" ${filters.category===v?'checked':''}>${t}</label>`).join('')}</div><div class="filter-block"><h3>Za vaš tim</h3><label class="filter-option"><input type="radio" name="role" data-filter="role" value="all" ${filters.role==='all'?'checked':''}>Sve grupe</label>${roles.map(v=>`<label class="filter-option"><input type="radio" name="role" data-filter="role" value="${esc(v)}" ${filters.role===v?'checked':''}>${esc(v)}</label>`).join('')}</div><div class="filter-block"><h3>Dodatni izbor</h3><label class="filter-option"><input type="checkbox" data-filter="available" ${filters.available?'checked':''}>Samo dostupni</label><label class="filter-option"><input type="checkbox" data-filter="favorites" ${filters.favorites?'checked':''}>Omiljeni modeli</label><button class="text-btn mt20" data-action="clear-filters">Poništi filtere</button></div></aside><section><div class="catalog-toolbar"><form id="catalog-search" class="search-field">${ic('search')}<input name="q" value="${esc(filters.q)}" placeholder="Naziv proizvoda ili šifra…" aria-label="Pretraga proizvoda"></form><select class="select" aria-label="Sortiranje" id="sort"><option value="recommended">Preporučeni izbor</option><option value="price-up" ${filters.sort==='price-up'?'selected':''}>Cena: niža ka višoj</option><option value="price-down" ${filters.sort==='price-down'?'selected':''}>Cena: viša ka nižoj</option><option value="name" ${filters.sort==='name'?'selected':''}>Naziv: A–Ž</option></select></div><p class="result-count">${pp.length} proizvoda · Cene bez PDV-a · Sve prikazane cene i zalihe su demo podaci</p><div class="product-grid catalog-grid">${pp.map(card).join('')||`<div class="empty no-results">${ic('search')}<h2>Nema rezultata</h2><p>Pokušajte drugu pretragu ili uklonite filtere.</p><button class="btn light" data-action="clear-filters">Prikaži sve proizvode</button></div>`}</div></section></div>`;}
 function programs(){const c=customer();return `${heading('Naše uniforme','Vaši odobreni modeli i sačuvane specifikacije. Spremni za sledeću smenu.',`<button class="btn light small" data-action="quote-new">${ic('plus')}Novi model za tim</button>`)}<div class="notice">${ic('info')}<p>Izaberite broj komada po veličini. Personalizacija je već sačuvana za <strong>${esc(c.name)}</strong>. Prikazane specifikacije i odobrenja služe demonstraciji.</p></div><div class="program-grid">${c.approved.map(id=>product(id)).filter(Boolean).map((p,i)=>`<article class="program-card"><div class="program-image"><img src="${p.image}" alt="${esc(p.name)}"><span class="badge green">${ic('check')}Odobren model</span></div><form class="program-body" data-form="program" data-id="${p.id}"><div class="eyebrow">${esc(p.role)}</div><h2>${esc(p.name)}</h2><p>Standardni izbor za ${esc(c.shortName)} tim.</p><dl class="spec-list"><dt>Personalizacija</dt><dd>${esc(c.logo)} · vez na grudima</dd><dt>Referenca</dt><dd>${esc(c.shortName.toUpperCase())}-UN-${String(i+1).padStart(2,'0')}</dd><dt>Vaša demo cena</dt><dd>${money(price(p))} / kom</dd></dl><div class="size-matrix">${p.sizes.map(s=>`<label class="size-cell">${esc(s)}<input name="qty_${esc(s)}" type="number" min="0" max="999" value="0" aria-label="Količina ${esc(p.name)}, veličina ${esc(s)}"></label>`).join('')}</div><input type="hidden" name="logo" value="${esc(c.logo)}"><button class="btn full" type="submit">${ic('bag')}Dodaj izabrane veličine</button></form></article>`).join('')}</div>`;}
 function ordersPage(){const a=isAdmin();let oo=(a?state.orders:mineOrders()).filter(o=>(orderFilter==='all'||o.status===orderFilter)&&(!adminSearch||(o.id+' '+(state.customers.find(c=>c.id===o.customerId)?.name||'')).toLowerCase().includes(adminSearch.toLowerCase())));return `${heading(a?'Porudžbine kupaca':'Moje porudžbine',a?'Od prijema do isporuke — svi zahtevi vašeg tima na jednom mestu.':'Statusi, detalji i ponovno poručivanje iz prethodne nabavke.',`<button class="btn light small" data-action="export-orders">${ic('download')}Izvoz CSV</button>`)}<div class="tabs">${[['all','Sve'],['received','Primljene'],['confirmed','Potvrđene'],['production','U pripremi'],['shipped','Poslate'],['delivered','Isporučene']].map(([v,t])=>`<button class="tab ${orderFilter===v?'active':''}" data-action="order-filter" data-value="${v}">${t}</button>`).join('')}</div>${a?`<form id="admin-search" class="search-field mb20">${ic('search')}<input name="q" value="${esc(adminSearch)}" placeholder="Broj porudžbine ili naziv kupca" aria-label="Pretraži porudžbine"></form>`:''}<div class="panel no-pad"><div class="table-scroll"><table class="data-table"><thead><tr><th>Porudžbina</th>${a?'<th>Kupac</th>':''}<th>Datum</th><th>Komada</th><th>Iznos bez PDV-a</th><th>Status</th><th></th></tr></thead><tbody>${oo.map(o=>`<tr><td><button class="text-btn" data-action="order" data-id="${o.id}">${o.id}</button><small class="muted" style="display:block;font-size:9px">${esc(o.reference||'Redovna nabavka')}</small></td>${a?`<td>${esc(state.customers.find(c=>c.id===o.customerId)?.name||'')}</td>`:''}<td class="nowrap">${date(o.date)}</td><td>${o.items.reduce((s,l)=>s+l.qty,0)}</td><td class="nowrap"><strong>${money(total(o.items))}</strong></td><td>${badge(o.status)}</td><td><button class="btn light small" data-action="${a?'order':'reorder'}" data-id="${o.id}">${a?'Otvori':ic('repeat')+'Ponovi'}</button></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty">Nema porudžbina za ovaj izbor.</div></td></tr>'}</tbody></table></div></div>`;}
 function quick(){return `${heading('Brza porudžbina','Dodajte više artikala odjednom, bez traženja svakog modela u katalogu.')}<div class="two-col"><section class="panel"><h2>Uvezite svoj spisak</h2><p class="muted" style="font-size:11px">Podržani formati: CSV, XLSX, TXT i XML. Količine unesite kao cele brojeve.</p><label class="dropzone" id="dropzone">${ic('upload')}<strong>Prevucite fajl ili kliknite za izbor</strong><span>Šifra · Veličina · Količina</span><input id="import-file" type="file" accept=".csv,.txt,.xml,.xlsx"></label><div class="flex wrap"><button class="text-btn" data-action="download-template">${ic('download')}Preuzmi CSV šablon</button><button class="text-btn" data-action="import-sample">Probaj sa primerom</button></div><hr class="rule"><h3>Ili nalepite podatke</h3><textarea class="import-text" id="import-text" aria-label="Spisak artikala" placeholder="sifra;velicina;kolicina&#10;${products[0].sku};M;5&#10;${products[1].sku};L;3"></textarea><button class="btn" data-action="import-text">Proveri spisak ${ic('arrow')}</button></section><aside class="panel"><div class="eyebrow">MANJE PREPISIVANJA</div><h2>Od spiska do korpe.</h2><div class="pilot-steps"><div class="pilot-step"><div><strong>Koristite šifre iz demo kataloga</strong>Za isti artikal i više veličina koristite zaseban red po veličini.</div></div><div class="pilot-step"><div><strong>Proverite pre dodavanja</strong>Portal prikazuje pronađene modele, cenu i eventualne greške.</div></div><div class="pilot-step"><div><strong>Potvrdite korpu</strong>Ispravni redovi mogu se dodati u korpu, uz sačuvanu personalizaciju vašeg objekta.</div></div></div><div class="notice mt20">${ic('info')}<p>U ovoj demonstraciji fajl se obrađuje samo u vašem pregledaču. XML koristi elemente <strong>artikal</strong> sa poljima <strong>sifra, velicina, kolicina</strong>.</p></div></aside></div><div id="import-preview" class="mt20">${importPreview()}</div>`;}
 function importPreview(){if(!importRows.length)return '';const valid=importRows.filter(r=>!r.error);return `<section class="panel no-pad"><div class="panel-head"><h2>Provera spiska</h2><span class="badge ${valid.length===importRows.length?'green':'orange'}">${valid.length} od ${importRows.length} ispravnih redova</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Šifra</th><th>Artikal</th><th>Veličina</th><th>Količina</th><th>Provera</th></tr></thead><tbody>${importRows.map(r=>`<tr class="${r.error?'error-row':''}"><td>${esc(r.sku)}</td><td>${esc(r.p?.name||'—')}</td><td>${esc(r.size)}</td><td>${esc(r.qty)}</td><td>${r.error?`<span style="color:var(--red)">${esc(r.error)}</span>`:'<span class="badge green">Ispravno</span>'}</td></tr>`).join('')}</tbody></table></div><div style="padding:18px"><button class="btn" data-action="import-add" ${!valid.length?'disabled':''}>Dodaj ispravne stavke u korpu (${valid.length}) ${ic('arrow')}</button></div></section>`;}
 function cartPage(){const c=customer(),items=state.cart,net=total(items),vat=Math.round(net*.2);return `${heading('Vaša korpa',`${items.length} stavki · ${cartCount()} komada · ${esc(c.name)}`,items.length?'<button class="text-btn" data-action="clear-cart">Isprazni korpu</button>':'')} ${!items.length?`<div class="empty">${ic('bag')}<h2>Spremni za sledeću nabavku?</h2><p>Izaberite odobrene uniforme za svoj tim ili istražite katalog.</p><a href="#programs" class="btn">Naše uniforme ${ic('arrow')}</a></div>`:`<div class="cart-layout"><section class="panel">${items.map((l,i)=>{const p=product(l.productId);return `<div class="cart-item"><img src="${p.image}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><p>Veličina: ${esc(l.size)} · ${esc(l.logo||'Bez personalizacije')}</p><div class="unit">${money(linePrice(l))} / kom, bez PDV-a</div><div class="qty-control"><button data-action="cart-qty" data-index="${i}" data-delta="-1" aria-label="Umanji količinu">−</button><input type="number" min="1" max="999" value="${l.qty}" data-cart-index="${i}" aria-label="Količina za ${esc(p.name)} ${esc(l.size)}"><button data-action="cart-qty" data-index="${i}" data-delta="1" aria-label="Uvećaj količinu">+</button></div><button class="text-btn" style="font-size:9px;margin-left:12px;color:#9a9e90" data-action="cart-remove" data-index="${i}">Ukloni</button></div><div class="item-total">${money(linePrice(l)*l.qty)}</div></div>`;}).join('')}<div class="notice mt20">${ic('shield')}<p>Sačuvana specifikacija: <strong>${esc(c.logo)}</strong>. Rokovi i dostupnost potvrđuju se pri obradi porudžbine.</p></div><a class="text-btn" href="#catalog">${ic('plus')}Dodajte još artikala</a></section><aside><form id="checkout" class="panel"><h2>Pregled nabavke</h2><div class="summary-line"><span>Osnovica</span><strong>${money(net)}</strong></div><div class="summary-line"><span>PDV 20%</span><strong>${money(vat)}</strong></div><div class="summary-line"><span>Dostava</span><span>Po potvrdi</span></div><div class="summary-line total"><span>Ukupno</span><span>${money(net+vat)}</span></div><hr class="rule"><div class="form-group"><label for="delivery">Objekat za isporuku</label><select name="delivery" id="delivery">${c.locations.map(l=>`<option>${esc(l)}</option>`).join('')}</select></div><div class="form-group"><label for="reference">Vaša referenca</label><input name="reference" id="reference" maxlength="80" placeholder="Npr. Nova smena — novembar"></div><div class="form-group"><label for="order-note">Napomena</label><textarea id="order-note" name="note" maxlength="1000" placeholder="Željeni rok ili dodatne informacije"></textarea></div><label class="check-label"><input type="checkbox" required name="confirm">Potvrđujem izabrane veličine i specifikaciju personalizacije.</label><button class="btn brand full" type="submit">Pošalji demo porudžbinu ${ic('arrow')}</button><p class="checkout-note">Ovo je probna porudžbina. Nema naplate niti slanja podataka dobavljaču. Možete je otvoriti i obraditi u administraciji ovog pregledača.</p></form></aside></div>`}`;}
 function quotesPage(){const a=isAdmin(),qq=a?state.quotes:myQuotes();return `${heading('Ponude i zahtevi',a?'Pripremite ponudu, unesite dogovorenu cenu i prosledite je kupcu.':'Poseban model, veća količina ili novi izgled tima — dogovor počinje ovde.',!a?'<button class="btn" data-action="quote-new">'+ic('plus')+'Novi zahtev</button>':'')}<div class="panel no-pad"><div class="table-scroll"><table class="data-table"><thead><tr><th>Zahtev</th>${a?'<th>Kupac</th>':''}<th>Predmet</th><th>Datum</th><th>Status</th><th></th></tr></thead><tbody>${qq.map(q=>`<tr><td><strong>${q.id}</strong></td>${a?`<td>${esc(state.customers.find(c=>c.id===q.customerId)?.name||'')}</td>`:''}<td class="table-title">${esc(q.subject)}<small>${esc(product(q.productId)?.name||'Izbor modela sa dobavljačem')} · ${q.qty} kom</small></td><td>${date(q.date)}</td><td>${badge(q.status,true)}</td><td><button class="btn light small" data-action="quote" data-id="${q.id}">${a?'Obradi':'Detalji'}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">Još nema zahteva za ponudu.</div></td></tr>'}</tbody></table></div></div>`;}
 function documentsPage(){const oo=mineOrders().filter(o=>o.status!=='cancelled');return `${heading('Dokumenti','Specifikacije i pregledi vaših nabavki, uvek pri ruci.')}<div class="notice">${ic('info')}<p>Dokumenti u demou su pregledi porudžbina i specifikacija. Ne predstavljaju fakture, fiskalne račune niti potvrdu stvarne isporuke.</p></div><div class="panel no-pad"><div class="table-scroll"><table class="data-table"><thead><tr><th>Dokument</th><th>Porudžbina</th><th>Datum</th><th></th></tr></thead><tbody>${oo.map(o=>`<tr><td><span class="flex">${ic('docs')}Pregled porudžbine i specifikacija</span></td><td>${o.id}</td><td>${date(o.date)}</td><td><button class="btn light small" data-action="download-order" data-id="${o.id}">${ic('download')}Preuzmi</button></td></tr>`).join('')}</tbody></table></div></div>`;}
 function accountPage(){const c=customer();return `${heading('Moj nalog','Podaci vašeg objekta i uslovi saradnje.')}<div class="two-col"><form id="account-form" class="panel"><h2>Kontakt i personalizacija</h2><p class="muted" style="font-size:11px">Izmene važe samo u ovoj demonstraciji.</p><div class="form-group"><label>Naziv kupca</label><input value="${esc(c.name)}" disabled></div><div class="form-grid"><div class="form-group"><label>Kontakt osoba</label><input name="contact" value="${esc(c.contact)}" required maxlength="80"></div><div class="form-group"><label>Email</label><input name="email" type="email" value="${esc(c.email)}" required maxlength="120"></div></div><div class="form-group"><label>Tekst / oznaka odobrenog logotipa</label><input name="logo" value="${esc(c.logo)}" required maxlength="80"><small>Prikaz oznake odobrene specifikacije; ne predstavlja produkcioni fajl za vez.</small></div><button class="btn" type="submit">Sačuvaj izmene</button></form><section class="panel"><div class="eyebrow">UGOVORENI USLOVI · DEMO</div><h2>${esc(c.name)}</h2><dl class="spec-list"><dt>Rabat</dt><dd>${c.discount}% na demo osnovicu</dd><dt>Plaćanje</dt><dd>${c.paymentDays} dana</dd><dt>Odobreni modeli</dt><dd>${c.approved.length} modela</dd><dt>Status naloga</dt><dd>Aktivan demo nalog</dd></dl><hr class="rule"><h3>Lokacije za isporuku</h3>${c.locations.map(l=>`<p class="muted" style="font-size:11px">${esc(l)}</p>`).join('')}<button class="text-btn mt20" data-action="profiles">${ic('switch')}Isprobajte drugi nalog</button></section></div>`;}
 function helpPage(){return `${heading('Tu smo za vaš tim.','Kratka uputstva za pregled i isprobavanje portala.')}<div class="two-col"><section class="panel"><h2>Kako da isprobate demo</h2>${[['Kako da ponovim nabavku uniformi?','Otvorite „Naše uniforme”, unesite komade po veličini i dodajte ih u korpu. Sačuvana oznaka logotipa prenosi se uz svaku stavku. U korpi izaberite objekat i pošaljite probnu porudžbinu.'],['Kako da vidim obradu porudžbine?','Kliknite „Administracija” u gornjem desnom uglu. Otvorite „Porudžbine”, pronađite novu porudžbinu i promenite status. Vratite se na prikaz kupca — promena je odmah vidljiva u istom pregledaču.'],['Mogu li da pošaljem zahtev za ponudu?','Da. Izaberite „Ponude i zahtevi”, pa „Novi zahtev”. U administraciji možete uneti jediničnu cenu i poslati demo ponudu. Kupac zatim može da je prihvati i kreira porudžbinu.'],['Da li su proizvodi i cene stvarni?','Nazivi, fotografije i javni opisi proizvoda preuzeti su sa hotelskaoprema.rs. Sve ugovorene cene, raspoložive količine, nalozi, statusi i poslovni dokumenti su ilustrativni. Izvorni proizvod možete otvoriti iz njegovih detalja.'],['Da li demo šalje porudžbine ili email poruke?','Ne. Sve promene se čuvaju samo u lokalnom prostoru ovog pregledača. Ne postoji stvarna prijava, naplata, slanje poruka ni ERP povezivanje. Podaci se ne sinhronizuju između uređaja.']].map(([q,a])=>`<details class="help-detail"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section><div class="contact-box">${ic('phone')}<div><h3>Razgovarajte sa Dejanom</h3><p>Za stvarne proizvode i poslovne upite.</p><a href="tel:+381607480048">+381 60 748 00 48</a></div></div><div class="contact-box">${ic('mail')}<div><h3>Hotelska oprema</h3><p>Otvara vaš program za email; demo ne šalje poruke.</p><a href="mailto:info@hotelskaoprema.rs">info@hotelskaoprema.rs</a></div></div><div class="panel"><h3>Ponovite demonstraciju</h3><p class="muted" style="font-size:11px">Vratite početne podatke i uklonite sve probne porudžbine, ponude i izmene.</p><button class="btn danger small" data-action="reset">${ic('repeat')}Vrati početni demo</button></div></section></div>`;}
 function adminDashboard(){const pending=state.orders.filter(o=>o.status==='received'),net=state.orders.filter(o=>o.status!=='cancelled').reduce((s,o)=>s+total(o.items),0);return `${heading('Dobar dan, Dejane.','Pregled nabavki, kupaca i prvih koraka vašeg partner portala.',`<span class="badge green">Demo administracija</span>`)}<section class="admin-intro"><div><div class="eyebrow">PILOT UMESTO PRETPOSTAVKI</div><h2>Koliko kupaca bi koristilo portal?</h2><p>Počnite sa malom grupom stalnih kupaca uniformi. Pratite aktivaciju naloga, prvu nabavku i ponovljene porudžbine.</p></div><a href="#pilot" class="btn light">Pregled pilot grupe ${ic('arrow')}</a></section><div class="kpi-grid">${kpi('Primljene porudžbine',pending.length,'Čekaju vašu potvrdu','orders')}${kpi('Vrednost demo porudžbina',money(net),'Ukupna osnovica svih demo naloga','chart')}${kpi('Zahtevi za ponudu',state.quotes.filter(q=>q.status==='requested').length,'Čekaju pripremu ponude','quote')}${kpi('Kupci u pilot grupi',state.customers.filter(c=>c.pilot).length,'Ilustrativna grupa za početak','users')}</div><section class="panel no-pad"><div class="panel-head"><h2>Poslednje porudžbine</h2><a href="#orders" class="text-btn">Sve porudžbine ${ic('arrow')}</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Porudžbina</th><th>Kupac</th><th>Datum</th><th>Vrednost</th><th>Status</th><th></th></tr></thead><tbody>${state.orders.slice(0,5).map(o=>`<tr><td><strong>${o.id}</strong></td><td>${esc(state.customers.find(c=>c.id===o.customerId)?.name||'')}</td><td>${date(o.date)}</td><td>${money(total(o.items))}</td><td>${badge(o.status)}</td><td><button class="btn light small" data-action="order" data-id="${o.id}">Obradi</button></td></tr>`).join('')}</tbody></table></div></section><div class="dashboard-lower"><section class="panel"><div class="eyebrow">ZDRAVLJE KATALOGA</div><h2>Spremno za kupce</h2><dl class="spec-list"><dt>Artikli</dt><dd>${products.length} stvarnih proizvoda sa sajta</dd><dt>Uniforme</dt><dd>${products.filter(p=>p.category==='uniforme').length} modela</dd><dt>Zalihe</dt><dd>Ilustrativne, mogu se menjati</dd></dl><a href="#inventory" class="text-btn">Upravljaj artiklima ${ic('arrow')}</a></section><section class="panel help-panel"><div class="eyebrow">SLEDEĆI KORAK</div><h2>Prvi kupac.<br>Prva porudžbina.</h2><p>Izaberite kupca, pogledajte njegove odobrene modele i prođite ceo tok nabavke.</p><button class="text-btn" data-action="toggle-mode">Otvori prikaz kupca ${ic('arrow')}</button></section></div>`;}
 function customersPage(){return `${heading('Poslovni kupci','Odobreni modeli, ugovoreni uslovi i status aktivacije.',`<button class="btn small" data-action="customer-new">${ic('plus')}Dodaj demo kupca</button>`)}<div class="notice">${ic('info')}<p>Svi kupci i njihovi kontakti su izmišljeni. Dugme „Otvori nalog” prikazuje iskustvo izabranog kupca u ovoj demonstraciji.</p></div><div class="panel no-pad"><div class="table-scroll"><table class="data-table"><thead><tr><th>Kupac</th><th>Kontakt</th><th>Modeli</th><th>Rabat</th><th>Pilot</th><th></th></tr></thead><tbody>${state.customers.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small class="muted" style="display:block">${esc(c.locations[0])}</small></td><td>${esc(c.contact)}<small class="muted" style="display:block">${esc(c.email)}</small></td><td>${c.approved.length}</td><td>${c.discount}%</td><td><label class="check-label"><input type="checkbox" data-pilot="${c.id}" ${c.pilot?'checked':''}>U grupi</label></td><td><button class="btn light small" data-action="customer-open" data-id="${c.id}">Otvori nalog ${ic('arrow')}</button></td></tr>`).join('')}</tbody></table></div></div>`;}
 function inventoryPage(){return `${heading('Artikli i zalihe','Stvarni proizvodi. Ilustrativne količine za proveru toka rada.',`<button class="btn light small" data-action="download-template">${ic('download')}Šifre artikala</button>`)}<div class="panel no-pad"><div class="table-scroll"><table class="data-table"><thead><tr><th>Artikal</th><th>Grupa</th><th>Šifra u demou</th><th>Ukupno komada</th><th></th></tr></thead><tbody>${products.map(p=>`<tr><td><div class="flex"><img class="thumb" src="${p.image}" alt=""><span class="table-title"><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></span></div></td><td>${esc(p.category)}</td><td>${p.sku}</td><td><input class="admin-price" type="number" min="0" max="100000" step="1" value="${stock(p)}" data-stock="${p.id}" aria-label="Ukupna demo zaliha: ${esc(p.name)}"></td><td><button class="text-btn" data-action="product" data-id="${p.id}">Detalji</button></td></tr>`).join('')}</tbody></table></div></div>`;}
 function pricingPage(){return `${heading('Cene i uslovi','Prikažite kako individualni uslovi menjaju cene na nalogu kupca.')}<div class="notice">${ic('info')}<p>Ovo nisu javne niti potvrđene ugovorene cene dobavljača. Rabati se primenjuju na ilustrativnu osnovicu proizvoda. Sačuvane porudžbine zadržavaju cenu iz trenutka kreiranja.</p></div><div class="two-col">${state.customers.map(c=>`<form class="panel" data-form="pricing" data-id="${c.id}"><div class="flex gap8 mb20"><span class="avatar">${esc(c.initials)}</span><h2 style="margin:0;font-size:17px">${esc(c.name)}</h2></div><div class="form-grid"><div class="form-group"><label>Rabat na demo osnovicu (%)</label><input type="number" name="discount" min="0" max="50" step="1" value="${c.discount}" required></div><div class="form-group"><label>Rok plaćanja (dana)</label><input type="number" name="paymentDays" min="0" max="120" step="1" value="${c.paymentDays}" required></div></div><p class="muted" style="font-size:11px">Primer: ${esc(products[0].name)}<br><strong>${money(price(products[0],c))}</strong> / kom bez PDV-a</p><button class="btn small" type="submit">Sačuvaj uslove</button></form>`).join('')}</div>`;}
 function pilotPage(){const cc=state.customers.filter(c=>c.pilot),invited=cc.filter(c=>c.invited).length,activated=cc.filter(c=>c.activated).length,buyers=cc.filter(c=>state.orders.some(o=>o.customerId===c.id&&o.status!=='cancelled')).length,repeat=cc.filter(c=>state.orders.filter(o=>o.customerId===c.id&&o.status!=='cancelled').length>1).length,pct=(n,d)=>d?Math.round(n/d*100):0;return `${heading('Od interesovanja do navike.','Ilustrativan pilot: proverite usvajanje portala kod male grupe stalnih kupaca.',`<a class="btn light small" href="#customers">${ic('users')}Izaberi kupce</a>`)}<div class="notice blue">${ic('info')}<p>Podaci u ovom pregledu su demo primer. Ne predstavljaju stvarno korišćenje kupaca. Pozivanje i aktivacija se ovde samo simuliraju; nove probne porudžbine ažuriraju pregled.</p></div><div class="kpi-grid">${kpi('Kupci u pilotu',cc.length,'Odabrani poslovni kupci','users')}${kpi('Aktivirani nalozi',activated,`${pct(activated,invited)}% od pozvanih (demo)`,'user')}${kpi('Prva porudžbina',buyers,'Kupci sa bar jednom nabavkom','bag')}${kpi('Ponovljena nabavka',repeat,'Kupci sa dve ili više porudžbina','repeat')}</div><div class="two-col"><section class="panel"><div class="eyebrow">OD POZIVA DO PORUDŽBINE</div><h2>Gde kupcima treba pomoć?</h2><div class="adoption-bars">${[['Odabrani kupci',cc.length],['Pozvani u demo',invited],['Aktivirali nalog',activated],['Napravili porudžbinu',buyers],['Ponovili nabavku',repeat]].map(([t,n],i)=>`<div class="adoption-row"><div><span>${t}</span><strong>${n} / ${cc.length}</strong></div><div class="bar-track"><div class="bar-fill ${i>2?'green':''}" style="width:${pct(n,cc.length)}%"></div></div></div>`).join('')}</div></section><section class="panel"><div class="eyebrow">PREDLOG ZA PRVU FAZU</div><h2>Prvo mali, poznat krug.</h2><div class="pilot-steps"><div class="pilot-step"><div><strong>Odaberite stalne kupce uniformi</strong>Počnite sa 5–10 kupaca koji već naručuju iste modele i specifikacije.</div></div><div class="pilot-step"><div><strong>Pripremite njihov izbor</strong>Unesite odobrene modele, oznaku personalizacije i dogovorene uslove.</div></div><div class="pilot-step"><div><strong>Pomozite kod prve nabavke</strong>Kratko pokažite poručivanje po veličinama i ponavljanje porudžbine.</div></div><div class="pilot-step"><div><strong>Procena nakon dogovorenog perioda</strong>Uporedite aktivne kupce, ponovljene nabavke i ručni rad pre proširenja.</div></div></div></section></div><section class="panel no-pad mt20"><div class="panel-head"><h2>Pilot grupa</h2><span class="badge">Demo aktivacije</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Kupac</th><th>Poziv</th><th>Aktivacija</th><th>Porudžbine</th><th>Sledeći korak</th></tr></thead><tbody>${cc.map(c=>{const count=state.orders.filter(o=>o.customerId===c.id&&o.status!=='cancelled').length;return `<tr><td><strong>${esc(c.name)}</strong></td><td>${c.invited?'Pozvan':'Nije pozvan'}</td><td>${c.activated?'<span class="badge green">Aktivan</span>':'<span class="badge orange">Na čekanju</span>'}</td><td>${count}</td><td>${!c.invited?`<button class="btn light small" data-action="pilot-invite" data-id="${c.id}">Simuliraj poziv</button>`:!c.activated?`<button class="btn light small" data-action="pilot-activate" data-id="${c.id}">Simuliraj aktivaciju</button>`:`<button class="text-btn" data-action="customer-open" data-id="${c.id}">Otvori nalog ${ic('arrow')}</button>`}</td></tr>`;}).join('')||'<tr><td colspan="5">Izaberite kupce na stranici „Kupci”.</td></tr>'}</tbody></table></div></section>`;}
 function modal(title,body,narrow=false){modalReturn=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Zatvori dijalog">${ic('close')}</button></div><div class="modal-content">${body}</div></section></div>`;document.body.style.overflow='hidden';wireLabels(document.getElementById('modal-root'));const first=document.querySelector('.modal button,.modal input,.modal select');first?.focus();}
 function closeModal(){document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';modalReturn?.focus?.();}
 function productModal(id){const p=product(id);if(!p)return;modal(p.name,`<div class="product-modal-grid"><div><img class="detail-image" src="${p.image}" alt="${esc(p.name)}"><p class="source-description">Stvarni proizvod i fotografija sa sajta dobavljača. Šifra ${p.sku}, cene i zalihe u portalu su demo podaci.</p><a class="product-source" href="${esc(p.source_url)}" target="_blank" rel="noopener">Pogledajte izvorni proizvod ↗</a></div><form data-form="product" data-id="${p.id}"><div class="eyebrow">${esc(p.role)} · ${p.sku}</div><p class="detail-description">${esc(p.description)}</p><span class="badge ${stock(p)>0?'green':'orange'}">${stock(p)>0?'Demo raspoloživo: '+stock(p)+' kom ukupno':'Demo nabavka po porudžbini'}</span><div class="detail-price">${money(price(p))}</div><div class="detail-note">Ilustrativna ugovorena cena po komadu, bez PDV-a.</div><div class="size-matrix">${p.sizes.map(s=>`<label class="size-cell">${esc(s)}<input type="number" min="0" max="999" value="0" name="qty_${esc(s)}" aria-label="Količina za veličinu ${esc(s)}"></label>`).join('')}</div>${p.category==='uniforme'?`<div class="form-group"><label>Personalizacija</label><select name="logo"><option value="${esc(customer().logo)}">Sačuvana specifikacija: ${esc(customer().logo)}</option><option value="Bez personalizacije">Bez personalizacije</option><option value="Nova personalizacija — potvrda potrebna">Nova personalizacija — potrebna potvrda</option></select><small>Novi logo i tehnička priprema potvrđuju se kroz ponudu. Doplate nisu obračunate.</small></div>`:'<input type="hidden" name="logo" value="Bez personalizacije">'}<p class="detail-note">Veličine služe demonstraciji izbora; tačnu tabelu mera potvrđuje dobavljač.</p><div class="form-error" id="product-error"></div><button class="btn full" type="submit">${ic('bag')}Dodaj u korpu</button><button class="btn light full mt20" type="button" data-action="quote-new" data-id="${p.id}">Zatraži posebnu ponudu</button></form></div>`);}
 function addLines(id,fd){const p=product(id);let count=0;const lines=[];for(const s of p.sizes){const n=Number(fd.get('qty_'+s)||0);if(!Number.isInteger(n)||n<0||n>999){toast('Unesite ceo broj od 0 do 999.');return false;}if(n){count+=n;lines.push({productId:id,size:s,qty:n,logo:String(fd.get('logo')||customer().logo),unitPrice:price(p)});}}if(!count){toast('Unesite količinu za bar jednu veličinu.');return false;}if(count<(p.minQty||1)){toast('Minimalna količina za ovaj artikal je '+p.minQty+' komada.');return false;}for(const l of lines)mergeLine(l);save();return true;}
 function mergeLine(l){const existing=state.cart.find(x=>x.productId===l.productId&&x.size===l.size&&x.logo===l.logo&&x.unitPrice===l.unitPrice);if(existing)existing.qty=Math.min(999,existing.qty+l.qty);else state.cart.push(l);}
 function profileModal(){modal('Izaberite demo prikaz',`<p class="muted" style="font-size:12px">Nije potrebna registracija. Svi podaci su izmišljeni i promene ostaju u ovom pregledaču.</p><div class="profiles-grid">${state.customers.map(c=>`<button class="profile-choice" data-action="customer-open" data-id="${c.id}"><span class="avatar">${esc(c.initials)}</span><h3>${esc(c.name)}</h3><p>${esc(c.contact)} · ${c.discount}% demo rabata<br>${c.approved.length} odobrenih modela</p></button>`).join('')}<button class="profile-choice admin" data-action="admin-open"><div class="flex">${ic('shield')}<strong>Administracija — Dejan</strong></div><p class="mt20">Obradite porudžbinu, pripremite ponudu i pogledajte pilot grupu.</p></button></div>`);}
 function showOrder(id){const o=state.orders.find(o=>o.id===id);if(!o)return;if(!isAdmin()&&o.customerId!==state.profileId)return;const c=state.customers.find(c=>c.id===o.customerId),sequence=['received','confirmed','production','shipped','delivered'],idx=sequence.indexOf(o.status);modal('Porudžbina '+o.id,`<div class="flex between wrap"><span class="muted" style="font-size:11px">${date(o.date)} · ${esc(c.name)}</span>${badge(o.status)}</div>${o.status!=='cancelled'?`<div class="status-timeline">${sequence.map((s,i)=>`<div class="timeline-step ${i<=idx?'done':''}">${statuses[s][0]}</div>`).join('')}</div>`:''}<div class="order-detail-info"><div><h3>Isporuka</h3><p>${esc(o.delivery||c.locations[0])}</p><p>${esc(c.contact)}</p><p>${esc(c.email)}</p></div><div><h3>Vaša referenca</h3><p>${esc(o.reference||'Redovna nabavka')}</p><h3 style="margin-top:12px">Napomena</h3><p>${esc(o.note||'Nema dodatnih napomena.')}</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Artikal / specifikacija</th><th>Veličina</th><th>Komada</th><th>Iznos</th></tr></thead><tbody>${o.items.map(l=>`<tr><td><strong>${esc(product(l.productId)?.name||'Artikal')}</strong><small class="muted" style="display:block">${esc(l.logo||'Bez personalizacije')}</small></td><td>${esc(l.size)}</td><td>${l.qty}</td><td class="nowrap">${money(linePrice(l)*l.qty)}</td></tr>`).join('')}</tbody></table></div><div class="summary-line"><span>Osnovica</span><strong>${money(total(o.items))}</strong></div><div class="summary-line"><span>PDV 20%</span><strong>${money(total(o.items)*.2)}</strong></div><div class="summary-line total"><span>Ukupno sa PDV-om</span><span>${money(total(o.items)*1.2)}</span></div>${isAdmin()?`<form class="quote-box" data-form="status" data-id="${o.id}"><div class="form-grid"><div class="form-group"><label>Status porudžbine</label><select name="status">${Object.entries(statuses).map(([s,[t]])=>`<option value="${s}" ${o.status===s?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-group"><label>Napomena za kupca</label><input name="note" value="${esc(o.note||'')}" maxlength="1000"></div></div><button type="submit" class="btn">Sačuvaj status ${ic('check')}</button></form>`:''}<div class="modal-actions"><button class="btn light" data-action="download-order" data-id="${o.id}">${ic('download')}Preuzmi pregled</button>${!isAdmin()?`<button class="btn" data-action="reorder" data-id="${o.id}">${ic('repeat')}Ponovi porudžbinu</button>`:''}</div><p class="checkout-note">Probni dokument i demo status. Nije poslato dobavljaču i nema finansijske obaveze.</p>`);}
 function quoteNew(id){modal('Novi zahtev za ponudu',`<p class="muted" style="font-size:12px">Opišite novi model, personalizaciju ili planiranu nabavku. Zahtev se u ovoj demonstraciji pojavljuje u administraciji.</p><form id="quote-form"><div class="form-group"><label>Predmet zahteva</label><input name="subject" required maxlength="120" placeholder="Npr. Uniforme za novu recepcijsku smenu"></div><div class="form-grid"><div class="form-group"><label>Model</label><select name="productId">${products.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="form-group"><label>Okvirna količina</label><input name="qty" type="number" min="1" max="999" value="20" required></div></div><div class="form-group"><label>Specifikacija i raspodela veličina</label><textarea name="note" required maxlength="1500" placeholder="Boja, logo, željeni rok, broj komada po veličinama…"></textarea></div><div class="notice">${ic('info')}<p>Demo zahtev. Ne šalje se email niti poruka dobavljaču.</p></div><button class="btn full" type="submit">Sačuvaj demo zahtev ${ic('arrow')}</button></form>`,true);}
 function showQuote(id){const q=state.quotes.find(q=>q.id===id);if(!q)return;if(!isAdmin()&&q.customerId!==state.profileId)return;const p=product(q.productId),c=state.customers.find(c=>c.id===q.customerId);modal('Zahtev '+q.id,`<div class="flex between wrap"><span class="muted" style="font-size:11px">${esc(c.name)} · ${date(q.date)}</span>${badge(q.status,true)}</div><h2 class="mt20">${esc(q.subject)}</h2><p class="detail-description">${esc(p?.name||'Dogovor modela')} · ${q.qty} komada</p><div class="quote-box"><strong style="font-size:12px">Zahtev kupca</strong><p style="white-space:pre-wrap">${esc(q.note)}</p></div>${q.adminNote?`<div class="notice green">${ic('check')}<p>${esc(q.adminNote)}</p></div>`:''}${isAdmin()&&q.status!=='accepted'?`<form data-form="offer" data-id="${q.id}"><div class="form-grid"><div class="form-group"><label>Demo jedinična cena bez PDV-a (RSD)</label><input name="unitPrice" type="number" min="1" max="1000000" value="${q.unitPrice||price(p,c)}" required></div><div class="form-group"><label>Ukupna tražena količina</label><input value="${q.qty} komada" disabled></div></div><h3>Raspodela po veličinama</h3><div class="size-matrix">${p.sizes.map(z=>`<label class="size-cell">${esc(z)}<input type="number" min="0" max="999" name="offer_qty_${esc(z)}" value="${q.allocations?.[z]??(z===(q.size||p.sizes[0])&&!q.allocations?q.qty:0)}" aria-label="Ponuda, veličina ${esc(z)}"></label>`).join('')}</div><div class="form-group"><label>Odgovor / uslovi ponude</label><textarea name="adminNote" required maxlength="1500">${esc(q.adminNote||'Model i personalizacija prema odobrenoj specifikaciji. Rok isporuke potvrđujemo nakon dogovora.')}</textarea><small>Zbir izabranih veličina treba da odgovara traženoj količini.</small></div><button class="btn" type="submit">Pošalji demo ponudu kupcu ${ic('arrow')}</button></form>`:q.status==='offered'?`<div class="summary-line"><span>Ponuđena jedinična cena</span><strong>${money(q.unitPrice)}</strong></div><div class="summary-line"><span>Veličina / količina</span><span>${Object.entries(q.allocations||{[q.size||p.sizes[0]]:q.qty}).filter(([z,n])=>n>0).map(([z,n])=>esc(z)+": "+n).join(" · ")} / ${q.qty} kom</span></div><div class="summary-line total"><span>Osnovica</span><span>${money(q.unitPrice*q.qty)}</span></div><button class="btn brand full" data-action="accept-quote" data-id="${q.id}">Prihvati demo ponudu i kreiraj porudžbinu</button>`:q.status==='accepted'?`<div class="notice green">${ic('check')}<p>Ponuda je prihvaćena. Kreirana je porudžbina <strong>${esc(q.orderId)}</strong>.</p></div>`:'<p class="muted" style="font-size:12px">Zahtev čeka pripremu ponude. Možete ga obraditi u administraciji.</p>'}`,true);}
 function nextId(prefix,list){let n=1061;while(list.some(x=>x.id===prefix+n))n++;return prefix+n;}
 function createOrder(items,details={}){const c=customer();const o={id:nextId('HO-',state.orders),customerId:state.profileId,date:today(),status:'received',items:clone(items),delivery:details.delivery||c.locations[0],reference:details.reference||'',note:details.note||''};state.orders.unshift(o);c.activated=true;c.invited=true;save();return o;}
 function orderSuccess(o){modal('Porudžbina je sačuvana',`<div class="order-success"><div class="success-circle">${ic('check')}</div><h2>Hvala. Vaš tim je korak bliže.</h2><p>Probna porudžbina <strong>${o.id}</strong> sačuvana je u ovom pregledaču. Otvorite je u administraciji i isprobajte potvrdu i promenu statusa.</p><div class="flex wrap" style="justify-content:center"><button class="btn light" data-action="success-orders">Moje porudžbine</button><button class="btn" data-action="admin-order" data-id="${o.id}">Obradi u administraciji ${ic('arrow')}</button></div><p class="checkout-note mt20">Nema naplate ni stvarne porudžbine.</p></div>`,true);}
 function download(name,data,type='text/plain;charset=utf-8'){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 const csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
 function exportOrders(){const oo=isAdmin()?state.orders:mineOrders(),rows=[['porudzbina','kupac','datum','status','komada','osnovica_RSD'],...oo.map(o=>[o.id,state.customers.find(c=>c.id===o.customerId)?.name,o.date,statuses[o.status][0],o.items.reduce((s,l)=>s+l.qty,0),total(o.items)])];download('demo-porudzbine.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
 function downloadOrder(id){const o=state.orders.find(o=>o.id===id);if(!o||(!isAdmin()&&o.customerId!==state.profileId))return;const c=state.customers.find(c=>c.id===o.customerId);download(o.id+'-demo-pregled.html',`<!doctype html><html lang="sr-Latn"><meta charset="utf-8"><title>${o.id} — Demo pregled</title><style>body{font:14px Arial;max-width:850px;margin:45px auto;padding:20px;color:#26333b}h1{font-size:28px}table{width:100%;border-collapse:collapse;margin:30px 0}td,th{padding:12px 8px;text-align:left;border-bottom:1px solid #ddd}small{color:#888}.notice{padding:15px;background:#f7f1e9}button{padding:10px 20px}@media print{button{display:none}}</style><h1>Hotelska oprema</h1><p>Pregled porudžbine ${o.id} · ${date(o.date)}</p><p class="notice">DEMO DOKUMENT — nije faktura, fiskalni račun niti stvarna porudžbina.</p><h3>${esc(c.name)}</h3><p>${esc(o.delivery)}<br>${esc(c.contact)}<br>Referenca: ${esc(o.reference)}</p><table><thead><tr><th>Artikal</th><th>Veličina</th><th>Kom</th><th>Jedinična cena</th><th>Osnovica</th></tr></thead><tbody>${o.items.map(l=>`<tr><td>${esc(product(l.productId).name)}<br><small>${esc(l.logo)}</small></td><td>${esc(l.size)}</td><td>${l.qty}</td><td>${money(linePrice(l))}</td><td>${money(linePrice(l)*l.qty)}</td></tr>`).join('')}</tbody></table><p>Osnovica: <strong>${money(total(o.items))}</strong><br>PDV 20%: ${money(total(o.items)*.2)}<br>Ukupno: <strong>${money(total(o.items)*1.2)}</strong></p><p>Napomena: ${esc(o.note)}</p><button onclick="window.print()">Štampaj / sačuvaj kao PDF</button></html>`,'text/html;charset=utf-8');}
 function parseCSV(text){const lines=[];let row=[],cell='',quoted=false;const delimiter=text.split(/\r?\n/)[0].includes(';')?';':text.split(/\r?\n/)[0].includes('\t')?'\t':',';for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell.trim());cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))lines.push(row);row=[];cell='';}else cell+=c;}row.push(cell.trim());if(row.some(Boolean))lines.push(row);return lines;}
 function validateRows(rows){if(!rows.length)throw Error('Spisak je prazan.');const first=rows[0].map(x=>String(x).replace(/^\uFEFF/,'').toLowerCase().trim());const header=first.some(x=>['sifra','šifra','sku','kolicina','količina','quantity','qty'].includes(x));const index=(names,fallback)=>{const i=first.findIndex(x=>names.includes(x));return i>=0?i:fallback;};const si=header?index(['sifra','šifra','sku'],0):0,zi=header?index(['velicina','veličina','size'],1):1,qi=header?index(['kolicina','količina','quantity','qty'],2):2;const rr=header?rows.slice(1):rows;if(rr.length>1000)throw Error('Demo podržava najviše 1.000 redova po uvozu.');importRows=rr.filter(r=>r.some(x=>String(x).trim())).map(r=>{const sku=String(r[si]??'').trim(),size=String(r[zi]??'').trim().toUpperCase(),qty=Number(r[qi]),p=products.find(p=>p.sku.toLowerCase()===sku.toLowerCase());let error='';if(!p)error='Šifra nije pronađena';else if(!p.sizes.includes(size))error='Veličina: '+p.sizes.join(', ');else if(!Number.isInteger(qty)||qty<1||qty>999)error='Količina mora biti ceo broj 1–999';return {sku,size,qty,p,error};});if(!importRows.length)throw Error('Nema redova sa artiklima.');render();document.getElementById('import-preview')?.scrollIntoView({behavior:'smooth',block:'start'});}
 async function parseXLSX(buffer){const bytes=new Uint8Array(buffer),dv=new DataView(buffer),files={};let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--){if(dv.getUint32(i,true)===0x06054b50){end=i;break;}}if(end<0)throw Error('XLSX fajl nije prepoznat.');const count=dv.getUint16(end+10,true);let pos=dv.getUint32(end+16,true);const decoder=new TextDecoder();for(let n=0;n<count;n++){if(dv.getUint32(pos,true)!==0x02014b50)break;const method=dv.getUint16(pos+10,true),size=dv.getUint32(pos+20,true),nl=dv.getUint16(pos+28,true),el=dv.getUint16(pos+30,true),cl=dv.getUint16(pos+32,true),offset=dv.getUint32(pos+42,true),name=decoder.decode(bytes.slice(pos+46,pos+46+nl));if(['xl/sharedStrings.xml','xl/worksheets/sheet1.xml'].includes(name)){const start=offset+30+dv.getUint16(offset+26,true)+dv.getUint16(offset+28,true);let content=bytes.slice(start,start+size);if(method===8){try{const stream=new Blob([content]).stream().pipeThrough(new DecompressionStream('deflate-raw'));content=new Uint8Array(await new Response(stream).arrayBuffer());}catch{throw Error('Ovaj pregledač ne podržava XLSX raspakivanje. Sačuvajte tabelu kao CSV.');}}else if(method!==0)throw Error('Nepodržan XLSX format. Koristite CSV.');files[name]=decoder.decode(content);}pos+=46+nl+el+cl;}const parser=new DOMParser(),ss=files['xl/sharedStrings.xml']?[...parser.parseFromString(files['xl/sharedStrings.xml'],'application/xml').getElementsByTagName('si')].map(x=>[...x.getElementsByTagName('t')].map(t=>t.textContent).join('')):[];if(!files['xl/worksheets/sheet1.xml'])throw Error('Prvi radni list nije pronađen. Koristite CSV šablon.');const xml=parser.parseFromString(files['xl/worksheets/sheet1.xml'],'application/xml');return [...xml.getElementsByTagName('row')].map(row=>{const arr=[];for(const c of row.getElementsByTagName('c')){const address=c.getAttribute('r')||'A1',letters=address.replace(/[0-9]/g,'');let index=0;for(const l of letters)index=index*26+l.charCodeAt(0)-64;const val=c.getElementsByTagName('v')[0]?.textContent||'',t=c.getAttribute('t');arr[index-1]=t==='s'?ss[Number(val)]:t==='inlineStr'?[...c.getElementsByTagName('t')].map(x=>x.textContent).join(''):val;}return arr;});}
 async function importFile(file){if(!file)return;if(file.size>5*1024*1024){toast('Fajl je prevelik. Najviše 5 MB.');return;}try{if(/\.xlsx$/i.test(file.name)){validateRows(await parseXLSX(await file.arrayBuffer()));}else{const text=await file.text();if(/\.xml$/i.test(file.name)){const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw Error('XML nije ispravan.');const elements=[...xml.getElementsByTagName('artikal')];if(!elements.length)throw Error('XML treba da sadrži elemente artikal.');validateRows(elements.map(e=>['sifra','velicina','kolicina'].map(n=>e.getElementsByTagName(n)[0]?.textContent||'')));}else if(/\.(csv|txt)$/i.test(file.name))validateRows(parseCSV(text));else throw Error('Izaberite CSV, TXT, XML ili XLSX.');}toast('Fajl je obrađen. Pregledajte redove.');}catch(e){toast(e.message||'Fajl nije moguće obraditi.');}}
 function sampleText(){return 'sifra;velicina;kolicina\n'+products.slice(0,3).map((p,i)=>`${p.sku};${p.sizes[Math.min(1,p.sizes.length-1)]};${[5,8,3][i]}`).join('\n');}
 function goto(v){if(location.hash!=='#'+v)history.pushState(null,'','#'+v);view=v;render();window.scrollTo(0,0);}
 document.addEventListener('click',e=>{
  const el=e.target.closest('[data-action]');if(!el){if(e.target.classList.contains('modal-backdrop'))closeModal();return;}e.preventDefault();const a=el.dataset.action,id=el.dataset.id;
  if(a==='product'){e.stopPropagation();productModal(id);}
  else if(a==='favorite'){e.stopPropagation();const i=state.favorites.indexOf(id);i>=0?state.favorites.splice(i,1):state.favorites.push(id);save();render();}
  else if(a==='close')closeModal();
  else if(a==='menu')document.getElementById('sidebar').classList.add('open');
  else if(a==='menu-close')document.getElementById('sidebar').classList.remove('open');
  else if(a==='profiles')profileModal();
  else if(a==='toggle-mode'){closeModal();state.mode=isAdmin()?'buyer':'admin';save();goto('dashboard');render();}
  else if(a==='admin-open'){closeModal();state.mode='admin';save();goto('dashboard');render();}
  else if(a==='customer-open'){closeModal();if(state.profileId!==id){if(state.cart.length&&!confirm('Promena kupca će isprazniti trenutnu korpu. Nastaviti?'))return;state.cart=[];}state.profileId=id;state.mode='buyer';state.customers.find(c=>c.id===id).activated=true;state.customers.find(c=>c.id===id).invited=true;save();goto('dashboard');render();}
  else if(a==='go-programs')goto('programs');else if(a==='go-pilot')goto('pilot');
  else if(a==='clear-filters'){filters={q:'',category:'all',role:'all',available:false,favorites:false,sort:'recommended'};render();}
  else if(a==='order')showOrder(id);
  else if(a==='reorder'){const o=state.orders.find(o=>o.id===id);if(!o||o.customerId!==state.profileId)return;for(const l of o.items)mergeLine({...clone(l),unitPrice:price(product(l.productId))});save();closeModal();goto('cart');render();toast('Prethodna nabavka je dodata. Proverite količine i nove demo cene.');}
  else if(a==='order-filter'){orderFilter=el.dataset.value;render();}
  else if(a==='export-orders')exportOrders();
  else if(a==='download-order')downloadOrder(id);
  else if(a==='quote-new')quoteNew(id);
  else if(a==='quote')showQuote(id);
  else if(a==='accept-quote'){const q=state.quotes.find(q=>q.id===id);if(!q||q.customerId!==state.profileId||q.status!=='offered')return;const lines=Object.entries(q.allocations||{[q.size||product(q.productId).sizes[0]]:q.qty}).filter(([z,n])=>n>0).map(([z,n])=>({productId:q.productId,size:z,qty:n,logo:customer().logo,unitPrice:q.unitPrice}));const o=createOrder(lines,{reference:'Prihvaćena ponuda '+q.id,note:q.adminNote});q.status='accepted';q.orderId=o.id;save();closeModal();goto('orders');render();orderSuccess(o);}
  else if(a==='clear-cart'){if(confirm('Isprazniti korpu?')){state.cart=[];save();render();}}
  else if(a==='cart-remove'){state.cart.splice(Number(el.dataset.index),1);save();render();}
  else if(a==='cart-qty'){const l=state.cart[Number(el.dataset.index)];l.qty=Math.max(1,Math.min(999,l.qty+Number(el.dataset.delta)));save();render();}
  else if(a==='success-orders'){closeModal();goto('orders');render();}
  else if(a==='admin-order'){closeModal();state.mode='admin';save();goto('orders');render();showOrder(id);}
  else if(a==='download-template')download('hotelska-oprema-demo-sablon.csv','\uFEFF'+sampleText(),'text/csv;charset=utf-8');
  else if(a==='import-sample'){document.getElementById('import-text').value=sampleText();validateRows(parseCSV(sampleText()));toast('Primer je spreman za pregled.');}
  else if(a==='import-text'){try{validateRows(parseCSV(document.getElementById('import-text').value));}catch(err){toast(err.message);}}
  else if(a==='import-add'){const valid=importRows.filter(r=>!r.error);for(const r of valid)mergeLine({productId:r.p.id,size:r.size,qty:r.qty,logo:r.p.category==='uniforme'?customer().logo:'Bez personalizacije',unitPrice:price(r.p)});importRows=[];save();goto('cart');render();toast('Ispravni redovi su dodati u korpu.');}
  else if(a==='pilot-invite'||a==='pilot-activate'){const c=state.customers.find(c=>c.id===id);c.invited=true;if(a==='pilot-activate')c.activated=true;save();render();toast(a==='pilot-invite'?'Demo poziv označen. Nijedna poruka nije poslata.':'Demo nalog je aktiviran.');}
  else if(a==='customer-new')modal('Dodaj demo kupca',`<form id="customer-form"><div class="form-group"><label>Naziv objekta</label><input name="name" required maxlength="80" placeholder="Npr. Hotel Javor (demo)"></div><div class="form-group"><label>Kontakt osoba</label><input name="contact" required maxlength="80" placeholder="Ime i prezime"></div><div class="form-group"><label>Lokacija</label><input name="location" required maxlength="140" placeholder="Adresa demo objekta"></div><p class="detail-note">Dobija ilustrativne uslove i prva tri modela uniformi. Nema slanja poziva.</p><button class="btn full" type="submit">Sačuvaj demo kupca</button></form>`,true);
  else if(a==='reset'){if(confirm('Vratiti početne podatke? Sve probne izmene u ovom pregledaču biće uklonjene.')){state=fresh();importRows=[];save();closeModal();goto('dashboard');render();toast('Početni demo je vraćen.');}}
  else if(a==='demo-info')modal('O ovoj demonstraciji',`<div class="eyebrow">HOTELSKA OPREMA × B2BWARE</div><h2>Jedna stvarna ideja. Podaci za probu.</h2><p class="detail-description">Portal prikazuje kako bi stalni kupci mogli da ponavljaju nabavke uniformi kroz svoj nalog. Proizvodi i fotografije su sa hotelskaoprema.rs; kupci, odobreni modeli, cene, zalihe i porudžbine su ilustrativni.</p><div class="notice">${ic('info')}<p>Promene se čuvaju samo u ovom pregledaču. Nema stvarne prijave, ERP veze, naplate ni slanja porudžbina. Administracija je otvorena isključivo za demonstraciju.</p></div><h3>Probajte ceo tok</h3><p class="detail-description">1. Naše uniforme → unesite veličine.<br>2. Korpa → pošaljite demo porudžbinu.<br>3. Administracija → otvorite i potvrdite porudžbinu.<br>4. Prikaz kupca → pogledajte novi status.</p><button class="btn" data-action="profiles">Izaberite prikaz ${ic('arrow')}</button>`,true);
 });
 document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,fd=new FormData(f),type=f.dataset.form,id=f.dataset.id;
  if(f.id==='top-search'||f.id==='catalog-search'){filters.q=String(fd.get('q')||'');goto('catalog');render();}
  else if(f.id==='admin-search'){adminSearch=String(fd.get('q')||'');render();}
  else if(type==='product'||type==='program'){if(addLines(id,fd)){if(type==='product')closeModal();render();toast('Veličine i personalizacija su dodate u korpu.');}}
  else if(f.id==='checkout'){if(!state.cart.length)return;for(const p of products){const qty=state.cart.filter(l=>l.productId===p.id).reduce((s,l)=>s+l.qty,0);if(qty>0&&qty<(p.minQty||1)){toast(p.name+': minimalno '+p.minQty+' komada.');return;}}const o=createOrder(state.cart,Object.fromEntries(fd));state.cart=[];save();goto('orders');render();orderSuccess(o);}
  else if(f.id==='quote-form'){const qty=Number(fd.get('qty'));if(!Number.isInteger(qty)||qty<1||qty>999)return;state.quotes.unshift({id:nextId('UP-',state.quotes),customerId:state.profileId,date:today(),status:'requested',subject:String(fd.get('subject')).trim(),productId:String(fd.get('productId')),qty,note:String(fd.get('note')).trim()});save();closeModal();goto('quotes');render();toast('Demo zahtev je sačuvan i vidljiv u administraciji.');}
  else if(type==='status'){const o=state.orders.find(o=>o.id===id);if(!isAdmin()||!o)return;o.status=String(fd.get('status'));o.note=String(fd.get('note'));save();closeModal();render();toast('Status je ažuriran i vidljiv kupcu.');}
  else if(type==='offer'){if(!isAdmin())return;const q=state.quotes.find(q=>q.id===id);q.unitPrice=Number(fd.get('unitPrice'));q.adminNote=String(fd.get('adminNote'));const allocations={};let sum=0;for(const z of product(q.productId).sizes){const n=Number(fd.get('offer_qty_'+z)||0);if(!Number.isInteger(n)||n<0||n>999){toast('Proverite količine po veličinama.');return;}if(n)allocations[z]=n;sum+=n;}if(sum!==q.qty){toast('Zbir veličina mora biti '+q.qty+' komada. Trenutno: '+sum+'.');return;}q.allocations=allocations;q.status='offered';save();closeModal();render();toast('Demo ponuda je spremna na nalogu kupca.');}
  else if(type==='pricing'){if(!isAdmin())return;const c=state.customers.find(c=>c.id===id);c.discount=Number(fd.get('discount'));c.paymentDays=Number(fd.get('paymentDays'));save();render();toast('Uslovi kupca su sačuvani.');}
  else if(f.id==='account-form'){const c=customer();c.contact=String(fd.get('contact')).trim();c.email=String(fd.get('email')).trim();c.logo=String(fd.get('logo')).trim();save();render();toast('Demo podaci su sačuvani.');}
  else if(f.id==='customer-form'){const name=String(fd.get('name')).trim(),contact=String(fd.get('contact')).trim();if(!name||!contact)return;state.customers.push({id:'customer-'+Date.now(),name,shortName:name,contact,firstName:contact.split(' ')[0],initials:name.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase(),email:'nabavka@example.com',logo:name.toUpperCase(),discount:10,paymentDays:15,locations:[String(fd.get('location')).trim()],approved:products.filter(p=>p.category==='uniforme').slice(0,3).map(p=>p.id),pilot:true,invited:false,activated:false});save();closeModal();render();toast('Demo kupac je dodat u pilot grupu.');}
 });
 document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){const key=el.dataset.filter;filters[key]=el.type==='checkbox'?el.checked:el.value;if(key==='category')filters.role='all';render();}else if(el.id==='sort'){filters.sort=el.value;render();}else if(el.id==='import-file')importFile(el.files[0]);else if(el.dataset.cartIndex!==undefined){const n=Number(el.value);if(!Number.isInteger(n)||n<1||n>999){toast('Količina mora biti ceo broj od 1 do 999.');render();return;}state.cart[Number(el.dataset.cartIndex)].qty=n;save();render();}else if(el.dataset.stock){if(!isAdmin())return;const n=Number(el.value);if(!Number.isInteger(n)||n<0||n>100000){toast('Unesite ceo broj od 0 do 100.000.');render();return;}state.inventory[el.dataset.stock]=n;save();toast('Demo zaliha je ažurirana.');}else if(el.dataset.pilot){state.customers.find(c=>c.id===el.dataset.pilot).pilot=el.checked;save();toast('Pilot grupa je ažurirana.');}});
 document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone'))e.preventDefault();});
 document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();importFile(e.dataTransfer.files[0]);}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.getElementById('sidebar')?.classList.remove('open');}if(e.key==='Enter'&&e.target.matches('.product-image'))productModal(e.target.dataset.id);if(e.key==='Tab'&&document.querySelector('.modal')){const els=[...document.querySelectorAll('.modal button,.modal a,.modal input,.modal select,.modal textarea')].filter(x=>!x.disabled&&x.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
 function onRoute(){const route=location.hash.replace('#','')||'dashboard',allowed=navigation().map(x=>x[0]).concat(['help',...(isAdmin()?[]:['cart','account'])]);view=allowed.includes(route)?route:'dashboard';closeModal();render();window.scrollTo(0,0);}
 window.addEventListener('hashchange',onRoute);window.addEventListener('popstate',onRoute);state.visits++;save();onRoute();
})();
